<?php
require_once __DIR__ . '/_init.php'; require_perfil(['Admin']); $erro='';
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $acao=$_POST['acao']??''; $id=(int)($_POST['id']??0); try { if($acao==='excluir') { $s=$pdo->prepare('DELETE FROM eventos WHERE id=:id'); $s->execute([':id'=>$id]); audit($pdo,'excluiu evento','eventos',$id); header('Location: eventos.php?ok=1'); exit; } if($acao==='salvar') { $titulo=trim((string)($_POST['titulo']??'')); $desc=trim((string)($_POST['descricao']??'')); $inicio=str_replace('T',' ',$_POST['data_inicio']??''); $fim=str_replace('T',' ',$_POST['data_fim']??''); $local=trim((string)($_POST['local']??'')); $link=trim((string)($_POST['link_inscricao']??'')); $curso=trim((string)($_POST['curso']??'')); $status=(string)($_POST['status']??'rascunho'); if($titulo===''||$desc===''||$inicio===''||!in_array($status,['rascunho','publicado','arquivado'],true)) throw new RuntimeException('Preencha título, descrição e data de início.'); if($fim!==''&&strtotime($fim)<strtotime($inicio)) throw new RuntimeException('A data final não pode anteceder a data inicial.'); if($link!==''&&!filter_var($link,FILTER_VALIDATE_URL)) throw new RuntimeException('O link de inscrição não é válido.'); $img=upload_image('imagem'); $vals=[':t'=>$titulo,':d'=>$desc,':img'=>$img,':i'=>$inicio,':f'=>$fim?:null,':l'=>$local?:null,':link'=>$link?:null,':curso'=>$curso?:null,':st'=>$status]; if($id) { $sql=$img?'UPDATE eventos SET titulo=:t,descricao=:d,imagem=:img,data_inicio=:i,data_fim=:f,local=:l,link_inscricao=:link,curso=:curso,status=:st WHERE id=:id':'UPDATE eventos SET titulo=:t,descricao=:d,data_inicio=:i,data_fim=:f,local=:l,link_inscricao=:link,curso=:curso,status=:st WHERE id=:id'; $vals[':id']=$id; $s=$pdo->prepare($sql); $s->execute($vals); audit($pdo,'editou evento','eventos',$id); } else { $s=$pdo->prepare('INSERT INTO eventos(titulo,descricao,imagem,data_inicio,data_fim,local,link_inscricao,curso,autor_id,status) VALUES(:t,:d,:img,:i,:f,:l,:link,:curso,:autor,:st) RETURNING id'); $vals[':autor']=$_SESSION['usuario_id']; $s->execute($vals); audit($pdo,'criou evento','eventos',(int)$s->fetchColumn()); } header('Location: eventos.php?ok=1'); exit; } } catch(Throwable $e) { if($e instanceof PDOException) error_log($e->getMessage()); $erro=($e instanceof RuntimeException&&!($e instanceof PDOException))?$e->getMessage():'Não foi possível salvar o evento. Confira os dados e a imagem.'; } }
$edit=null; if(isset($_GET['editar'])) { $s=$pdo->prepare('SELECT * FROM eventos WHERE id=:id'); $s->execute([':id'=>(int)$_GET['editar']]); $edit=$s->fetch(); } $items=$pdo->query('SELECT id,titulo,status,data_inicio,local FROM eventos ORDER BY data_inicio DESC')->fetchAll(); admin_header('Gerenciar eventos'); if($erro): ?><div class="alert error"><?= h($erro) ?></div><?php endif; ?><section class="panel"><h2><?= $edit?'Editar evento':'Criar evento' ?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Título<input name="titulo" maxlength="200" required value="<?= h($edit['titulo']??'') ?>"></label><label>Descrição completa<textarea name="descricao" rows="6" required><?= h($edit['descricao']??'') ?></textarea></label><label>Imagem do evento<input type="file" name="imagem" accept="image/jpeg,image/png,image/webp,image/gif"></label><?php if(!empty($edit['imagem'])): ?><img class="thumb" src="../<?= h($edit['imagem']) ?>" alt="Imagem atual"><?php endif; ?><label>Início<input type="datetime-local" name="data_inicio" required value="<?= !empty($edit['data_inicio'])?h(date('Y-m-d\TH:i',strtotime($edit['data_inicio']))):'' ?>"></label><label>Término<input type="datetime-local" name="data_fim" value="<?= !empty($edit['data_fim'])?h(date('Y-m-d\TH:i',strtotime($edit['data_fim']))):'' ?>"></label><label>Local<input name="local" maxlength="200" value="<?= h($edit['local']??'') ?>"></label><label>Curso relacionado (opcional)<input name="curso" maxlength="150" value="<?= h($edit['curso']??'') ?>"></label><label>Link de inscrição<input type="url" name="link_inscricao" value="<?= h($edit['link_inscricao']??'') ?>"></label><label>Estado<select name="status"><option value="rascunho" <?= (($edit['status']??'')==='rascunho')?'selected':'' ?>>Rascunho</option><option value="publicado" <?= (($edit['status']??'')==='publicado')?'selected':'' ?>>Publicado</option><option value="arquivado" <?= (($edit['status']??'')==='arquivado')?'selected':'' ?>>Arquivado</option></select></label><button type="submit">Salvar evento</button></form></section><section class="panel"><h2>Eventos cadastrados</h2><?php foreach($items as $it): ?><article class="item"><div><h3><?= h($it['titulo']) ?></h3><p><?= h(date('d/m/Y H:i',strtotime($it['data_inicio']))) ?> · <?= h($it['local']) ?> · <?= h($it['status']) ?></p></div><div class="actions"><a class="button secondary" href="eventos.php?editar=<?= (int)$it['id'] ?>">Editar</a><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><button class="danger" type="submit">Excluir</button></form></div></article><?php endforeach; ?></section><?php admin_footer();
